package vn.svframe.lively.integration.cobblemon;
import com.cobblemon.mod.common.api.pokemon.PokemonProperties;import com.cobblemon.mod.common.entity.pokemon.PokemonEntity;import net.minecraft.registry.RegistryKey;import net.minecraft.registry.RegistryKeys;import net.minecraft.server.MinecraftServer;import net.minecraft.server.world.ServerWorld;import net.minecraft.text.Text;import net.minecraft.util.Identifier;import net.minecraft.util.math.Vec3d;import vn.svframe.lively.npc.NpcBody;import vn.svframe.lively.npc.NpcDefinition;import java.util.Optional;import java.util.Set;import java.util.UUID;
/** Command-created Cobblemon body. It is never registered in Cobblemon natural spawning. */
public final class CobblemonPokemonBody implements NpcBody{private final UUID npcId;private PokemonEntity entity;public CobblemonPokemonBody(UUID id){npcId=id;}@Override public UUID npcId(){return npcId;}@Override public NpcDefinition.BodyType type(){return NpcDefinition.BodyType.EXTERNAL;}@Override public boolean spawned(){return entity!=null&&!entity.isRemoved();}@Override public Optional<UUID>entityUuid(){return spawned()?Optional.of(entity.getUuid()):Optional.empty();}@Override public Optional<Vec3d>position(){return spawned()?Optional.of(entity.getPos()):Optional.empty();}@Override public Optional<String>worldKey(){return spawned()?Optional.of(entity.getWorld().getRegistryKey().getValue().toString()):Optional.empty();}@Override public void spawn(MinecraftServer server,NpcDefinition d){if(spawned())return;ServerWorld world=world(server,d.world());if(world==null)throw new IllegalArgumentException("unknown world");String properties=d.bodyKey();if(properties.startsWith("cobblemon:"))properties=properties.substring("cobblemon:".length());PokemonProperties parsed=PokemonProperties.Companion.parse(properties);PokemonEntity created=parsed.createEntity(world);created.setUuid(npcId);created.refreshPositionAndAngles(d.x(),d.y(),d.z(),d.yaw(),d.pitch());created.setCustomName(Text.literal(d.name()));created.setCustomNameVisible(d.nameVisible());created.setInvulnerable(d.invulnerable());created.setNoGravity(!d.gravity());created.setSilent(d.silent());created.addCommandTag("lively");created.addCommandTag("lively_body");created.setPersistent();created.setAiDisabled(true);if(!world.spawnEntity(created))throw new IllegalStateException("Cobblemon world rejected Pokemon NPC body");entity=created;}@Override public void despawn(MinecraftServer server){if(entity!=null&&!entity.isRemoved())entity.discard();entity=null;}@Override public void teleport(MinecraftServer server,String worldKey,Vec3d position,float yaw,float pitch){if(!spawned())return;ServerWorld target=world(server,worldKey);if(target==null)return;if(entity.getWorld()!=target){boolean ok=entity.teleport(target,position.x,position.y,position.z,Set.of(),yaw,pitch);if(!ok){despawn(server);return;}PokemonEntity replacement=(PokemonEntity)target.getEntity(npcId);if(replacement!=null)entity=replacement;}else entity.refreshPositionAndAngles(position.x,position.y,position.z,yaw,pitch);}@Override public void moveStep(MinecraftServer server,String worldKey,Vec3d position,float yaw,float pitch){if(!spawned()||!worldKey().orElse("").equals(worldKey))return;entity.refreshPositionAndAngles(position.x,position.y,position.z,yaw,pitch);entity.setHeadYaw(yaw);}@Override public void lookAt(MinecraftServer server,Vec3d target){if(!spawned())return;Vec3d d=target.subtract(entity.getPos());double h=Math.sqrt(d.x*d.x+d.z*d.z);float yaw=(float)Math.toDegrees(Math.atan2(-d.x,d.z)),pitch=(float)-Math.toDegrees(Math.atan2(d.y,h));entity.setYaw(yaw);entity.setPitch(pitch);entity.setHeadYaw(yaw);}@Override public void tick(MinecraftServer server,NpcDefinition d){if(!spawned())return;entity.setCustomName(Text.literal(d.name()));entity.setCustomNameVisible(d.nameVisible());entity.setInvulnerable(d.invulnerable());entity.setNoGravity(!d.gravity());entity.setSilent(d.silent());}private static ServerWorld world(MinecraftServer server,String key){Identifier id=Identifier.tryParse(key);return id==null?null:server.getWorld(RegistryKey.of(RegistryKeys.WORLD,id));}}
